import re

from intentd.machine import (
    INTEL_PCI_ADDRESS,
    NVIDIA_PCI_ADDRESS,
    GraphicsBackend,
    MachineProfile,
)
from intentd.schema import CatalogApp, GraphicsProfile
from intentd.state import DesiredState


class RenderError(Exception):
    pass


_ATTR_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_'-]*$")

_NIX_KEYWORDS = frozenset({"if", "then", "else", "let", "in", "with", "rec", "assert", "inherit"})

_HEADER = "# Generated by intentd. Do not edit; manual changes block activation.\n"


def _render_graphics(profile: GraphicsProfile, machine_profile: MachineProfile | None) -> list[str]:
    if machine_profile is None:
        raise RenderError("graphics state requires a machine profile")
    if not machine_profile.certified:
        raise RenderError("graphics state requires a certified machine profile")
    if machine_profile.graphics_backend not in {
        GraphicsBackend.INTENTD_VM,
        GraphicsBackend.UX3404VC,
    }:
        raise RenderError("unsupported graphics backend")
    if machine_profile.intel_pci != INTEL_PCI_ADDRESS:
        raise RenderError("machine profile has an unsupported Intel PCI address")

    lines = [
        "  hardware.graphics.enable = true;",
        '  services.xserver.videoDrivers = [ "modesetting" ];',
    ]
    if profile is GraphicsProfile.HYBRID_NVIDIA:
        if machine_profile.nvidia_pci != NVIDIA_PCI_ADDRESS:
            raise RenderError("machine profile has an unsupported NVIDIA PCI address")
        lines = [
            "  hardware.graphics.enable = true;",
            '  services.xserver.videoDrivers = [ "modesetting" "nvidia" ];',
            "  hardware.nvidia.modesetting.enable = true;",
            "  hardware.nvidia.prime.offload.enable = true;",
            "  hardware.nvidia.prime.offload.enableOffloadCmd = true;",
            '  hardware.nvidia.prime.intelBusId = "PCI:0:2:0";',
            '  hardware.nvidia.prime.nvidiaBusId = "PCI:1:0:0";',
        ]
    return lines


def render(
    state: DesiredState,
    catalog: dict[str, CatalogApp],
    machine_profile: MachineProfile | None,
) -> str:
    packages: list[str] = []
    unfree: list[str] = []
    for app_id in state.apps:
        app = catalog.get(app_id)
        if app is None:
            raise RenderError(f"app {app_id!r} is not in the catalog")
        if app.id != app_id:
            raise RenderError(f"catalog entry id {app.id!r} does not match key {app_id!r}")
        if not _ATTR_RE.fullmatch(app.attr) or app.attr in _NIX_KEYWORDS:
            raise RenderError(f"attr {app.attr!r} fails the audited constructor pattern")
        packages.append(app.attr)
        if app.unfree:
            unfree.append(app.attr)
    lines = [
        _HEADER,
        "{ pkgs, lib, ... }:",
        "{",
        "  environment.systemPackages = [",
        *[f"    pkgs.{attr}" for attr in packages],
        "  ];",
    ]
    if unfree:
        lines += [
            "  nixpkgs.config.allowUnfreePredicate = pkg:",
            "    builtins.elem (lib.getName pkg) [",
            *[f'      "{attr}"' for attr in unfree],
            "    ];",
        ]
    if state.graphics_profile is not None:
        lines += _render_graphics(state.graphics_profile, machine_profile)
    lines.append("}")
    return "\n".join(lines) + "\n"
